const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const x = new Int32Array(n);
const y = new Int32Array(n);
let pos = 1;

for (let i = 0; i < n; i++) {
  x[i] = input[pos++];
  y[i] = input[pos++];
}

const pairCount = n * (n - 1) / 2;
const base = pairCount + n + 1;
const first = new Uint16Array(pairCount);
const second = new Uint16Array(pairCount);
const events = new Array(pairCount + n);

let id = 0;
for (let i = 0; i < n; i++) {
  for (let j = i + 1; j < n; j++) {
    const dx = x[i] - x[j];
    const dy = y[i] - y[j];
    const distanceSquared = dx * dx + dy * dy;

    first[id] = i;
    second[id] = j;
    events[id] = distanceSquared * base + id;
    id++;
  }
}

for (let i = 0; i < n; i++) {
  const distanceSquared = x[i] * x[i] + y[i] * y[i];
  events[pairCount + i] = distanceSquared * base + pairCount + i;
}

events.sort((a, b) => a - b);

const best = new Int32Array(n);
const pending = new Int32Array(n);
const touched = new Int32Array(n);
let answer = 0;
let end = events.length - 1;

while (end >= 0) {
  const weight = Math.floor(events[end] / base);
  let start = end;

  while (start > 0 && Math.floor(events[start - 1] / base) === weight) {
    start--;
  }

  let touchedCount = 0;

  for (let k = start; k <= end; k++) {
    const eventId = events[k] - weight * base;

    if (eventId < pairCount) {
      const a = first[eventId];
      const b = second[eventId];

      if (best[a] > 0) {
        const candidate = best[a] + 1;
        if (pending[b] === 0) touched[touchedCount++] = b;
        if (candidate > pending[b]) pending[b] = candidate;
      }

      if (best[b] > 0) {
        const candidate = best[b] + 1;
        if (pending[a] === 0) touched[touchedCount++] = a;
        if (candidate > pending[a]) pending[a] = candidate;
      }
    } else {
      const vertex = eventId - pairCount;
      if (pending[vertex] === 0) touched[touchedCount++] = vertex;
      if (pending[vertex] < 1) pending[vertex] = 1;
    }
  }

  for (let i = 0; i < touchedCount; i++) {
    const vertex = touched[i];
    if (pending[vertex] > best[vertex]) best[vertex] = pending[vertex];
    if (best[vertex] > answer) answer = best[vertex];
    pending[vertex] = 0;
  }

  end = start - 1;
}

console.log(answer.toString());
